import {aggregate,csvCell,dateValid,keyOf,normalize,roi} from './model.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:0}),money=n=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
let data,result,sort='revenue',direction=-1,page=1,pendingPage=1,visible=[],pendingKind='products',mappings={};
try{mappings=JSON.parse(localStorage.getItem('advanblack-mappings-v1')||'{}');}catch{}
const ratio=n=>n==null?'—':money(n);
const notice=text=>$('notice').textContent=text;
async function load(){try{const response=await fetch('/data.json');if(!response.ok){const error=await response.json();throw Error(error.error||'读取失败');}const first=!data;data=await response.json();if(first){$('start').value=data.coverage.start;$('end').value=data.coverage.end;}$('updated').textContent='数据保存于 '+new Date(data.updatedAt).toLocaleString('zh-CN');apply();}catch(e){notice(e.message);$('productRows').innerHTML='<tr><td colspan="7" class="empty">'+esc(e.message)+'</td></tr>';}}
function apply(){try{result=aggregate(data,$('start').value,$('end').value,mappings);page=pendingPage=1;notice(`已同步 ${data.coverage.start} — ${data.coverage.end}。GA4 日期按洛杉矶时间，广告日期按北京时间；统一以 USD 展示；Google 按固定汇率 6.8 换算。${data.dataNote||''}`);render();}catch(e){notice(e.message);result=null;$('metrics').replaceChildren();$('productRows').innerHTML='<tr><td colspan="7" class="empty">'+esc(e.message)+'</td></tr>';$('rowCount').textContent=$('pageLabel').textContent='';$('prev').disabled=$('next').disabled=true;$('auditContent').textContent=$('pendingContent').textContent=e.message;}}
function render(){const s=result.summary;$('metrics').innerHTML=[['站内商品收入 · USD','$ '+money(s.revenue),'GA4 全渠道 · 不含运费和税费'],['去重订单数',num(s.orders),'跨商品去重；各商品订单数不可相加'],['Meta 总消耗 · USD','$ '+money(s.meta),'Advanblack-03 + Advanblack-04'],['Google 总消耗 · USD','$ '+money(s.google),'包括暂不分配的非 PMax / Shopping'],['整体 ROI',ratio(roi(s.revenue,s.meta,s.google)),'站内商品收入 ÷（Meta + Google 总消耗）']].map(([l,v,h])=>`<article class="metric"><label>${l}</label><strong>${v}</strong><small>${h}</small></article>`).join('');renderProducts();renderPending();renderAudit();renderSources();}
function renderProducts(){if(!result)return;const q=$('search').value.trim().toLowerCase();visible=result.rows.filter(r=>r.title.toLowerCase().includes(q)).sort((a,b)=>(a[sort]==null?1:b[sort]==null?-1:direction*(a[sort]-b[sort]))||a.title.localeCompare(b.title));const pages=Math.max(1,Math.ceil(visible.length/30));page=Math.min(page,pages);$('productRows').innerHTML=visible.slice((page-1)*30,page*30).map(r=>`<tr><td><button class="product-link" data-product="${esc(r.title)}">${esc(r.title)}</button>${r.adRows?`<div class="small">${num(r.adRows)} 条广告商品记录${r.familyRows?` · 含型号归并`:``}</div>`:''}</td><td>${num(r.sessions)}</td><td>${num(r.orders)}</td><td>${money(r.revenue)}</td><td>${money(r.meta)}</td><td>${money(r.google)}</td><td>${ratio(r.roi)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有符合条件的商品</td></tr>';$('rowCount').textContent=`${num(visible.length)} 个商品 · 消耗 0.00 表示未计入匹配消耗，不代表商品没有广告费用`;$('pageLabel').textContent=`${page} / ${pages}`;$('prev').disabled=page===1;$('next').disabled=page===pages;document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>showDetails(b.dataset.product));}
function renderPending(){if(!result)return;const sorted=[...result.unmatched].sort((a,b)=>a.platform.localeCompare(b.platform)||b.cost-a.cost),rows=pendingKind==='products'?sorted:[...result.nonCatalog].sort((a,b)=>b.cost-a.cost),pages=Math.max(1,Math.ceil(rows.length/30));pendingPage=Math.min(pendingPage,pages);const slice=rows.slice((pendingPage-1)*30,pendingPage*30);
 $('pendingContent').innerHTML=`<div class="table-tools section-gap"><button id="pendingProducts" class="${pendingKind==='products'?'primary':''}">商品名待匹配 (${sorted.length})</button><button id="pendingAds" class="${pendingKind==='ads'?'primary':''}">未拆到产品的广告余额 (${result.nonCatalog.length})</button></div><div class="table-wrap"><table><thead><tr><th>${pendingKind==='products'?'广告商品 Title / ID':'广告名称'}</th><th>来源</th><th>消耗</th><th>可能对应的 GA4 商品</th></tr></thead><tbody>${slice.map((r,i)=>`<tr><td>${esc(pendingKind==='products'?r.title||'无商品标题':r.name)}<div class="small">${esc(r.id)}</div>${pendingKind==='ads'?r.links.slice(0,2).map(url=>/^https?:\/\//i.test(url)?`<div><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">查看落地页</a></div>`:'').join(''):''}</td><td>${pendingKind==='products'?(r.platform==='meta'?'Meta Product ID':r.type==='PERFORMANCE_MAX'?'PMax':'Shopping'):'Meta '+(r.account==='222947167250427'?'03':'04')}</td><td>${money(r.platform==='google'?r.cost/data.fx.cnyPerUsd:r.cost)} USD</td><td>${(r.candidates||[]).length?r.candidates.map(c=>`<div>${esc(c.title)} <span class="small">文字相似 ${c.score}%</span></div>`).join(''):'未找到可靠候选'}${pendingKind==='products'?`<div class="mapping-row"><input class="mapping-input" data-index="${i}" list="ga4Titles" placeholder="选择准确的 GA4 Title" aria-label="匹配目标商品"><button data-map="${i}">确认映射</button></div>`:'<div class="small">暂不分摊；候选来自广告名称、标题和已返回落地页</div>'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">没有待处理记录</td></tr>'}</tbody></table></div><div class="table-footer"><span>文字相似度不是匹配可信度，也不代表平台归因。</span><div><button id="pendingPrev" ${pendingPage===1?'disabled':''}>上一页</button><span>${pendingPage} / ${pages}</span><button id="pendingNext" ${pendingPage===pages?'disabled':''}>下一页</button></div></div><datalist id="ga4Titles">${[...new Set(data.ga4.map(x=>x.title))].sort().map(t=>`<option value="${esc(t)}">`).join('')}</datalist>`;
 $('pendingProducts').onclick=()=>{pendingKind='products';pendingPage=1;renderPending();};$('pendingAds').onclick=()=>{pendingKind='ads';pendingPage=1;renderPending();};$('pendingPrev').onclick=()=>{pendingPage--;renderPending();};$('pendingNext').onclick=()=>{pendingPage++;renderPending();};
 document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.map),title=document.querySelector(`.mapping-input[data-index="${index}"]`).value;if(!data.ga4.some(r=>r.title===title)){notice('请从 GA4 商品列表中选择完整且准确的 Title。');return;}mappings[slice[index].key]=title;localStorage.setItem('advanblack-mappings-v1',JSON.stringify(mappings));result=aggregate(data,$('start').value,$('end').value,mappings);render();notice('已保存本浏览器的商品映射，并重新计算消耗。可在「数据与口径」中撤销。');});
}
function renderAudit(){const row=(label,value)=>`<tr><td>${label}</td><td>${money(value)} USD</td></tr>`;$('auditContent').innerHTML=`<div class="source-grid">${result.accounts.map(a=>{const f=a.platform==='google'?data.fx.cnyPerUsd:1;return `<article class="source-card"><h3>${esc(a.name)}</h3><table><tbody>${row('账户总消耗',a.total/f)}${row('已匹配到 GA4 商品',a.matched/f)}${row('已拆到产品，商品名待匹配',(a.detail-a.matched)/f)}${row(a.platform==='meta'?'未拆到 Product ID / 报表差额':'PMax / Shopping 未拆到产品 / 报表差额',(a.eligible-a.detail)/f)}${a.platform==='google'?row('非 PMax / Shopping，暂不分配',(a.total-a.eligible)/f):''}</tbody></table><p>产品拆分覆盖：${a.eligible?((a.detail/a.eligible)*100).toFixed(1):'0.0'}% · 已拆分消耗的商品匹配率：${a.detail?((a.matched/a.detail)*100).toFixed(1):'0.0'}%</p>${a.platform==='google'?`<p>原始账户总额：${money(a.total)} CNY<br>用户指定固定汇率：1 USD = 6.8 CNY</p>`:''}</article>`}).join('')}</div><details><summary>查看 Google 暂不分配的广告系列</summary><table><thead><tr><th>广告系列</th><th>类型</th><th>消耗 USD</th></tr></thead><tbody>${googleOtherRows()}</tbody></table></details>`;}
function googleOtherRows(){const m=new Map();for(const r of result.totals.filter(r=>r.platform==='google'&&!['PERFORMANCE_MAX','SHOPPING'].includes(r.type))){const k=r.campaign;if(!m.has(k))m.set(k,{...r,cost:0});m.get(k).cost+=r.cost;}return [...m.values()].sort((a,b)=>b.cost-a.cost).map(r=>`<tr><td>${esc(r.campaign)}</td><td>${esc(r.type)}</td><td>${money(r.cost/data.fx.cnyPerUsd)}</td></tr>`).join('');}
function renderSources(){$('sourceContent').innerHTML=`<div class="source-grid"><article class="source-card"><h3>数据来源</h3><p>GA4：advanblack - GA4 · ${esc(data.sources.ga4.property)}<br>Google Ads：Advanblack · 9347478419<br>Meta：Advanblack-03 / Advanblack-04</p><p>覆盖：${data.coverage.start} — ${data.coverage.end}<br>GA4：USD · America/Los_Angeles<br>Google：原始 CNY → USD ÷ 6.8 · Asia/Shanghai<br>Meta：USD · Asia/Shanghai</p></article><article class="source-card"><h3>订单、Sessions 与收入</h3><p>订单数：包含该商品且有有效交易编号的购买记录，按交易编号去重。同一订单含多个商品时，各商品分别计 1 单，汇总卡片再次去重。</p><p>Sessions：GA4 商品维度的每日会话数汇总，不可跨商品相加当作全站会话。收入：itemRevenue，取所有渠道的商品收入，扣除商品退款，不含运费和税费。</p><p>缺少交易编号的记录：${result.summary.missingOrders} 条，未计入订单数。商品标题缺失和截断保留原状。</p></article><article class="source-card"><h3>商品匹配与广告范围</h3><p>主表保留 GA4 Title。仅唯一的规范化同名商品、按 SKU 和产品类型推断的型号归并及你确认的映射计入消耗；候选不会自动合并。</p><p>Meta 按 Product ID 汇总所有可拆分到商品的消耗，包含普通广告中的产品明细。没有 Product ID 明细的余额不分摊。Google 主表合并 PMax / Shopping 消耗，并以 CNY ÷ 6.8 换算为 USD，其他系列保留在核对页。</p><p>型号归并依据 SKU 系列和产品类型，属于规则推断，可点击商品查看来源。不同产品型号和配件不会仅凭文字相似自动合并。日期按各自账户时区筛选。</p></article><article class="source-card"><h3>报表查询与更新</h3><p>本页读取服务器已保存报表，不会因切换日期自动访问广告平台。已覆盖日期可随时查询，范围外会提示补充数据。</p><p>「刷新报表」重新读取已保存数据。「导入报表」上传本项目生成的 dashboard.json 并替换整份报表。平台自动拉数尚未接入，需另行配置服务器授权和同步程序。</p><p>手动商品映射保存在当前浏览器。服务器保留上一版导入报表供恢复；页面使用交易编号的哈希值去重。</p><button id="clearMappings">撤销本浏览器的手动映射（${Object.keys(mappings).length}）</button></article></div>`;$('clearMappings').onclick=()=>{if(Object.keys(mappings).length&&confirm('撤销所有手动商品映射？')){mappings={};localStorage.removeItem('advanblack-mappings-v1');apply();}};}
function range(days){if(!data)return;const end=data.coverage.end,date=new Date(end+'T12:00:00Z');date.setUTCDate(date.getUTCDate()-days+1);$('end').value=end;$('start').value=date.toISOString().slice(0,10);apply();}
$('filters').onsubmit=e=>{e.preventDefault();if(data)apply();};$('search').oninput=()=>{page=1;renderProducts();};$('prev').onclick=()=>{page--;renderProducts();};$('next').onclick=()=>{page++;renderProducts();};$('last7').onclick=()=>range(7);$('last14').onclick=()=>range(14);$('reload').onclick=load;
document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{direction=sort===b.dataset.sort?-direction:-1;sort=b.dataset.sort;page=1;renderProducts();});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));for(const id of ['products','pending','audit','sources'])$(id).hidden=id!==b.dataset.tab;});
$('export').onclick=()=>{if(!result)return;const lines=[['Title','Sessions','订单数','商品收入 USD','Meta USD','Google USD','ROI'],...visible.map(r=>[r.title,r.sessions,r.orders,r.revenue.toFixed(2),r.meta.toFixed(2),r.google.toFixed(2),r.roi==null?'':r.roi.toFixed(2)])].map(r=>r.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`Advanblack_${$('start').value}_${$('end').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'view_product_performance',description:'在已同步日期内查看商品表现并更新可见日期筛选。',inputSchema:{type:'object',properties:{start:{type:'string'},end:{type:'string'}},required:['start','end'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({start,end})=>{if(!data||!dateValid(start)||!dateValid(end))throw Error('数据未载入或日期无效');const check=aggregate(data,start,end,mappings);$('start').value=start;$('end').value=end;apply();return {products:check.rows.length,summary:check.summary};}});}catch{}}
load();

function showDetails(title){const exact=new Map();for(const t of new Set(data.ga4.map(r=>r.title))){const k=normalize(t);exact.set(k,exact.has(k)?null:t);}const m=new Map();for(const r of data.ads){if(r.date<$('start').value||r.date>$('end').value)continue;const key=keyOf(r);let target=mappings[key]||data.verifiedMappings[key];if(!target){target=exact.get(normalize(r.title));}if(target!==title)continue;const id=r.platform+'|'+r.id+'|'+r.title;if(!m.has(id))m.set(id,{...r,cost:0,reason:mappings[key]?'手动确认':data.mappingEvidence[key]?.rule||'规范化同名'});m.get(id).cost+=r.cost/(r.platform==='google'?data.fx.cnyPerUsd:1);}$('detailTitle').textContent=title;$('detailNote').textContent='按选定日期汇总。型号归并为规则推断；下表保留广告原始 Title 和 Product ID，可逐项核对。';$('detailRows').innerHTML=[...m.values()].sort((a,b)=>b.cost-a.cost).map(r=>`<tr><td>${esc(r.title)}<div class="small">${esc(r.id)}</div></td><td>${r.platform==='google'?'Google':'Meta'}</td><td>${esc(r.reason)}</td><td>${money(r.cost)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">此商品暂无已匹配的消耗，请查看待匹配产品。</td></tr>';$('detailDialog').showModal();}
$('closeDetail').onclick=()=>$('detailDialog').close();
